<｜｜DSML｜｜r>
<parameter=code>
import os

lines = []
for start in ['/home', '/workspace', '/root', '/tmp']:
    if not os.path.exists(start):
        lines.append(f"=== {start} NOT EXISTS ===")
        continue
    lines.append(f"=== {start} ===")
    try:
        for dirpath, dirnames, filenames in os.walk(start):
            dirnames[:] = [d for d in dirnames if d not in ['proc', 'sys', 'dev', 'node_modules', '.git', 'Library', 'System', 'Applications']]
            depth = dirpath[len(start):].count(os.sep)
            if depth > 7:
                dirnames[:] = []
                continue
            for fname in filenames:
                if fname in ['package.json', 'App.js', 'App.tsx', 'index.js', 'index.tsx']:
                    lines.append(f"  FILE: {os.path.join(dirpath, fname)}")
            if depth <= 3:
                lines.append(f"  DIR: {dirpath}")
    except Exception as e:
        lines.append(f"  ERROR: {e}")

with open('/tmp/explore.txt', 'w') as f:
    f.write('\n'.join(lines))
print("DONE, wrote", len(lines), "lines")
